class Solution {
public:
    vector<string> removeInvalidParentheses(string s) {
        int leftRemove = 0, rightRemove = 0;
        for (char c : s) {
            if (c == '(') {
                leftRemove++;
            } else if (c == ')') {
                if (leftRemove > 0) leftRemove--;
                else rightRemove++;
            }
        }
        unordered_set<string> result;
        string cur;
        dfs(s, 0, leftRemove, rightRemove, 0, cur, result);
        return vector<string>(result.begin(), result.end());
    }

private:
    void dfs(const string& s, int i, int lr, int rr, int open,
             string& cur, unordered_set<string>& result) {
        if (i == (int)s.size()) {
            if (lr == 0 && rr == 0 && open == 0)
                result.insert(cur);
            return;
        }
        char c = s[i];
        if (c == '(') {
            if (lr > 0)
                dfs(s, i + 1, lr - 1, rr, open, cur, result);
            cur.push_back(c);
            dfs(s, i + 1, lr, rr, open + 1, cur, result);
            cur.pop_back();
        } else if (c == ')') {
            if (rr > 0)
                dfs(s, i + 1, lr, rr - 1, open, cur, result);
            if (open > 0) {
                cur.push_back(c);
                dfs(s, i + 1, lr, rr, open - 1, cur, result);
                cur.pop_back();
            }
        } else {
            cur.push_back(c);
            dfs(s, i + 1, lr, rr, open, cur, result);
            cur.pop_back();
        }
    }
};
